MDJ([
{"n":"Antiépileptiques","i":"antiepileptiques","s":"neuro","nn":["Antiépileptiques","Antiépileptiques bloqueurs des canaux sodiques","Antiépileptiques modulateurs du GABA","Antiépileptiques agissant sur les canaux calciques","Barbituriques anticonvulsivants","Anticonvulsivants pédiatriques","Valproate","Lévétiracétam"],"d":["Les **antiépileptiques** préviennent la récidive des **crises d'épilepsie**. Le traitement est souvent prolongé (plusieurs années, parfois à vie) et doit être pris **très régulièrement** : un oubli ou un arrêt brutal peut déclencher des crises, voire un état de mal.","Plusieurs sont aussi utilisés comme **thymorégulateurs** (troubles bipolaires) ou contre les **douleurs neuropathiques**."],"ma":["Ils diminuent l'**excitabilité des neurones** : blocage des canaux sodiques (carbamazépine, lamotrigine, phénytoïne, lacosamide), renforcement du **GABA**, principal frein du cerveau (valproate, phénobarbital, benzodiazépines), action sur les canaux calciques ou la libération des neurotransmetteurs (lévétiracétam, gabapentinoïdes)."],"sch":{"k":"neurone","cap":"Les antiépileptiques freinent la transmission excessive de l'influx nerveux."},"m":[{"dci":"Valproate de sodium","br":"Dépakine®, Micropakine®","pr":"large spectre ; **tératogène majeur**"},{"dci":"Lévétiracétam","br":"Keppra®","pr":"très utilisé, oral ou IV"},{"dci":"Lamotrigine","br":"Lamictal®","pr":"augmentation très progressive (éruptions)"},{"dci":"Carbamazépine, oxcarbazépine","br":"Tégrétol®, Trileptal®","pr":"inducteurs enzymatiques ; hyponatrémie"},{"dci":"Phénytoïne, fosphénytoïne","br":"Di-Hydan®, Prodilantin®","pr":"marge étroite ; état de mal (IV)"},{"dci":"Lacosamide, topiramate, zonisamide","br":"Vimpat®, Epitomax®, Zonegran®","pr":"autres molécules"},{"dci":"Phénobarbital","br":"Gardénal®","pr":"barbiturique ; sédatif, inducteur"}],"ind":["**Épilepsie** (crises focales ou généralisées)","**État de mal épileptique** (après les benzodiazépines : lévétiracétam, valproate, fosphénytoïne ou phénobarbital IV)","Trouble bipolaire (valproate, lamotrigine, carbamazépine), douleurs neuropathiques (carbamazépine, gabapentinoïdes), migraine (topiramate)"],"ci":["**Valproate** : **femme en âge de procréer et grossesse**, sauf absence d'alternative et respect du programme de prévention des grossesses ; hépatite, porphyrie","Carbamazépine : bloc auriculoventriculaire, antécédent d'aplasie médullaire","Lamotrigine : antécédent de réaction cutanée grave","Hypersensibilité"],"ef":["**Somnolence**, vertiges, troubles de l'équilibre, fatigue","Valproate : **prise de poids**, tremblements, chute de cheveux","Lévétiracétam : **irritabilité**, troubles de l'humeur","Topiramate : perte de poids, paresthésies, troubles cognitifs"],"eg":["**Malformations et troubles du neurodéveloppement** (valproate pendant la grossesse : jusqu'à 10 % de malformations et 30 à 40 % de troubles du développement)","**Réactions cutanées graves** (lamotrigine, carbamazépine, phénytoïne) : Stevens-Johnson, Lyell, DRESS","**Hépatite** et **pancréatite** (valproate), **hyponatrémie** (carbamazépine, oxcarbazépine), cytopénies","Troubles du rythme (lacosamide, phénytoïne IV), idées suicidaires"],"it":["**Carbamazépine, phénytoïne, phénobarbital = inducteurs enzymatiques** : rendent inefficaces la **contraception hormonale**, les AVK, les AOD, de nombreux médicaments","**Valproate + carbapénèmes** : effondrement du taux de valproate (crises)","Valproate + lamotrigine : taux de lamotrigine augmenté (éruptions)","Alcool et sédatifs : somnolence"],"v":["Voie orale, **à heures fixes**, sans oubli ; formes LP à ne pas écraser","Introduction **progressive** (lamotrigine sur plusieurs semaines) ; **arrêt toujours progressif**","IV : lévétiracétam en perfusion de 15 minutes ; phénytoïne **sur une voie dédiée, diluée dans du NaCl 0,9 % uniquement**, lentement sous scope (veinotoxique, troubles du rythme)"],"sc":["**Crises** : fréquence, description, durée (calendrier des crises)","Vigilance, équilibre, humeur, comportement","**Peau** (éruption, surtout les 8 premières semaines), signes d'hépatite ou de pancréatite"],"sb":["**Dosages sanguins** (valproate, phénytoïne, carbamazépine, phénobarbital) si besoin ; NFS, bilan hépatique, natrémie, test de grossesse (valproate)"],"p":["Personne âgée : sensibilité accrue (confusion, chutes, hyponatrémie)","Enfant : formes buvables, doses au poids ; surveillance du développement et du comportement","Grossesse : **ne jamais arrêter brutalement** ; projet de grossesse à préparer avec le neurologue (changement de molécule, acide folique à forte dose)","Femme en âge de procréer sous valproate : **contraception efficace**, accord de soins annuel signé, tests de grossesse","Insuffisance rénale ou hépatique : adapter (lévétiracétam selon le rein, valproate contre-indiqué si hépatopathie)"],"edu":["Prendre le traitement **tous les jours aux mêmes heures** ; ne jamais l'arrêter seul","**Sommeil régulier**, éviter l'alcool et le manque de sommeil ; prudence pour la conduite (réglementation)","Contraception : signaler le traitement (inducteurs) ; projet de grossesse à discuter **avant**","Informer l'entourage de la conduite à tenir en cas de crise"],"cat":["Éruption cutanée : prévenir avant la dose suivante (toxidermie possible)","Crise : protéger, chronométrer, PLS après la crise, prévenir ; crise de plus de 5 minutes : benzodiazépine selon la prescription","Oubli de dose ou vomissement : prévenir pour la conduite à tenir"],"r":["Prise **régulière**, arrêt **progressif** ; arrêt brutal = risque d'état de mal","**Valproate tératogène** : contraception efficace, programme de prévention des grossesses","Éruptions graves (lamotrigine, carbamazépine) ; inducteurs enzymatiques : pilule inefficace","Phénytoïne IV : NaCl uniquement, voie dédiée, scope"],"err":[],"q":[{"q":"Quel risque majeur impose un encadrement strict du valproate chez la femme ?","o":["Une perte de cheveux","Un risque de malformations et de troubles du neurodéveloppement de l'enfant","Une hypoglycémie"],"a":1,"e":"Le valproate pendant la grossesse expose à des malformations et à des troubles du développement très fréquents."},{"q":"Que risque-t-on en arrêtant brutalement un antiépileptique ?","o":["Une hypertension","Une reprise des crises, voire un état de mal épileptique","Une diarrhée"],"a":1,"e":"L'arrêt brutal lève le frein exercé sur les neurones : les crises peuvent revenir de façon sévère."}],"f":["antiepileptiques","m:crise-convulsive","m:lithium"]},
{"n":"Benzodiazépines de la crise convulsive","i":"crise-convulsive","s":"neuro","nn":["Benzodiazépines anticonvulsivantes","Traitement de la crise convulsive","État de mal épileptique","Midazolam buccal","Buccolam","Diazépam intrarectal"],"d":["Une **crise convulsive** qui dure plus de **5 minutes** (ou des crises répétées sans reprise de conscience) définit l'**état de mal épileptique**, urgence vitale. Les **benzodiazépines** en sont le traitement de première intention, à administrer **sans attendre**, y compris par l'entourage (midazolam buccal chez l'enfant)."],"ma":["Les benzodiazépines renforcent l'action du **GABA**, frein des neurones, et arrêtent rapidement l'activité électrique anormale."],"sch":{"k":"synapse","cap":"Les benzodiazépines renforcent l'effet frein du GABA."},"m":[{"dci":"Midazolam buccal","br":"Buccolam®","pr":"seringues préremplies selon l'âge (enfant), dans la joue"},{"dci":"Diazépam","br":"Valium®","pr":"IV lente ou intrarectal (canule)"},{"dci":"Clonazépam","br":"Rivotril®","pr":"IV"},{"dci":"Midazolam","br":"Hypnovel®","pr":"IM ou IV (préhospitalier, réanimation)"}],"ind":["Crise convulsive de plus de 5 minutes, crises en série, **état de mal épileptique**","Convulsions fébriles prolongées de l'enfant","Sevrage alcoolique compliqué de convulsions"],"ci":["Pas de contre-indication en urgence vitale ; prudence en cas d'insuffisance respiratoire (matériel de ventilation prêt)"],"ef":["**Somnolence**, confusion au réveil","Hypotonie"],"eg":["**Dépression respiratoire** (doses répétées, association aux opioïdes, personne âgée)","Hypotension"],"it":[],"v":[],"sc":["**Durée de la crise** (chronométrer), description (début, mouvements, yeux, morsure, perte d'urines)","**Respiration**, SpO2, coloration, conscience après la crise","Glycémie capillaire, température (convulsion fébrile)"],"sb":["Glycémie, ionogramme (natrémie, calcémie), dosages des antiépileptiques, alcoolémie, toxiques selon le contexte"],"p":[],"edu":[],"cat":[],"r":["État de mal = crise de **plus de 5 minutes** : benzodiazépine **sans attendre**","Midazolam buccal (enfant), diazépam IV ou intrarectal, clonazépam IV","Surveiller la **respiration** ; deuxième dose possible, puis antiépileptique IV","Ne rien mettre dans la bouche ; PLS après la crise"],"err":[],"q":[],"f":["antiepileptiques","m:antiepileptiques","m:benzodiazepines"],"_l":1},
{"n":"Antiparkinsoniens","i":"parkinson","s":"neuro","nn":["Antiparkinsoniens dopaminergiques","Précurseurs de la dopamine","Agonistes dopaminergiques","Inhibiteurs de la COMT","Inhibiteurs de la MAO-B","Anticholinergiques antiparkinsoniens","Lévodopa","Modopar"],"d":["La **maladie de Parkinson** est due à la perte des neurones à **dopamine** : tremblement de repos, lenteur, raideur. Les antiparkinsoniens compensent ce manque de dopamine. Ils améliorent nettement les symptômes mais ne stoppent pas l'évolution."],"ma":["La **lévodopa**, précurseur, est transformée en dopamine dans le cerveau ; on l'associe à un inhibiteur de la décarboxylase (bensérazide, carbidopa) qui évite sa transformation hors du cerveau. Les **agonistes dopaminergiques** stimulent directement les récepteurs. Les **inhibiteurs de la COMT** et de la **MAO-B** ralentissent la dégradation de la dopamine."],"sch":{"k":"synapse","cap":"Les antiparkinsoniens augmentent la dopamine disponible dans la synapse ou stimulent ses récepteurs."},"m":[{"dci":"Lévodopa + bensérazide","br":"Modopar®","pr":"référence ; formes LP et dispersibles"},{"dci":"Lévodopa + carbidopa","br":"Sinemet® ; Duodopa® (gel intestinal)","pr":"référence"},{"dci":"Ropinirole, pramipexole, rotigotine","br":"Requip®, Sifrol®, Neupro® (patch)","pr":"agonistes dopaminergiques"},{"dci":"Apomorphine","br":"Apokinon®","pr":"stylo ou pompe SC"},{"dci":"Entacapone ; lévodopa + carbidopa + entacapone","br":"Comtan®, Stalevo®","pr":"inhibiteur de la COMT"},{"dci":"Rasagiline, safinamide","br":"Azilect®, Xadago®","pr":"inhibiteurs de la MAO-B"},{"dci":"Amantadine, trihexyphénidyle","br":"Mantadix®, Artane®","pr":"dyskinésies ; anticholinergique (tremblement)"}],"ind":["**Maladie de Parkinson**","Syndrome des jambes sans repos (agonistes dopaminergiques à faible dose)"],"ci":["Lévodopa : glaucome à angle fermé, psychose sévère","Agonistes : troubles psychiatriques sévères, antécédent de troubles du contrôle des impulsions","Anticholinergiques : personne âgée (confusion), glaucome, adénome de prostate"],"ef":["**Nausées**, vomissements (début de traitement)","**Hypotension orthostatique**","**Dyskinésies** (mouvements involontaires) et **fluctuations** (blocages « off ») après quelques années","Somnolence"],"eg":["**Hallucinations**, confusion, délire","**Troubles du contrôle des impulsions** (agonistes) : jeu pathologique, achats compulsifs, hypersexualité, boulimie","**Accès de sommeil brutaux** (conduite)","**Syndrome malin** en cas d'arrêt brutal : hyperthermie, rigidité, confusion"],"it":[],"v":[],"sc":["**Motricité** (blocages, dyskinésies) au fil de la journée, **horaires des prises**","**Tension couchée-debout**, chutes","Hallucinations, comportement, sommeil, déglutition, transit"],"sb":["Aucune surveillance biologique spécifique"],"p":[],"edu":[],"cat":[],"r":["Compenser la dopamine : lévodopa (+ inhibiteur), agonistes, ICOMT, IMAO-B","**Horaires stricts**, à distance des protéines ; jamais d'arrêt brutal","Hypotension orthostatique, hallucinations, **troubles du contrôle des impulsions**, accès de sommeil","**Jamais de métoclopramide ni d'antipsychotique classique** ; dompéridone pour les nausées"],"err":[],"q":[],"f":["m:antipsychotiques","m:antiemetiques"],"_l":1},
{"n":"Traitements de la maladie d'Alzheimer","i":"alzheimer","s":"neuro","nn":["Traitements de la maladie d'Alzheimer","Anticholinestérasiques","Donépézil","Rivastigmine","Mémantine"],"d":["La **maladie d'Alzheimer** altère progressivement la mémoire, le langage, l'orientation et l'autonomie. Les médicaments spécifiques (anticholinestérasiques, mémantine) ont un **effet modeste et transitoire** sur les symptômes ; ils ne sont plus remboursés en France depuis 2018 mais peuvent encore être prescrits."],"ma":["Les **anticholinestérasiques** (donépézil, rivastigmine, galantamine) freinent la dégradation de l'**acétylcholine**, neurotransmetteur de la mémoire. La **mémantine** bloque les récepteurs NMDA et limite l'excès de glutamate. Les anticholinestérasiques traitent aussi la **myasthénie** (pyridostigmine)."],"sch":null,"m":[{"dci":"Donépézil","br":"Aricept®","pr":"une prise le soir"},{"dci":"Rivastigmine","br":"Exelon® (gélules, patch)","pr":"patch changé chaque jour"},{"dci":"Galantamine","br":"Reminyl®","pr":"gélules LP"},{"dci":"Mémantine","br":"Ebixa®","pr":"formes modérées à sévères"},{"dci":"Pyridostigmine","br":"Mestinon®","pr":"myasthénie"}],"ind":["Maladie d'Alzheimer légère à modérée (anticholinestérasiques), modérée à sévère (mémantine)","Démence de la maladie de Parkinson (rivastigmine)","**Myasthénie** (pyridostigmine)"],"ci":["**Bradycardie**, troubles de la conduction, syncopes inexpliquées","Asthme sévère, ulcère évolutif (anticholinestérasiques)","Mémantine : insuffisance rénale sévère, épilepsie (prudence)"],"ef":["**Nausées, vomissements, diarrhée**, perte d'appétit et de poids","Insomnie, cauchemars (donépézil le soir), vertiges","Mémantine : vertiges, somnolence, constipation"],"eg":["**Bradycardie**, malaise, **syncope**, chutes","Perte de poids importante, déshydratation","Patch de rivastigmine : surdosage si plusieurs patchs sont laissés (vomissements, bradycardie)"],"it":[],"v":[],"sc":["**Pouls**, malaises, chutes","Poids, appétit, troubles digestifs, hydratation","Comportement, sommeil, autonomie, charge de l'aidant"],"sb":["ECG avant traitement si troubles cardiaques ; créatinine (mémantine)"],"p":[],"edu":[],"cat":[],"r":["Effet **modeste** ; non remboursés depuis 2018 ; l'accompagnement non médicamenteux est essentiel","Anticholinestérasiques : **troubles digestifs, bradycardie, syncope**","Patch de rivastigmine : **un seul patch**, retirer l'ancien","Éviter les anticholinergiques chez ces patients"],"err":[],"q":[],"f":["m:anticholinergiques","m:antipsychotiques"],"_l":1},
{"n":"Traitements de la sclérose en plaques","i":"sep","s":"neuro","nn":["Traitements de fond de la sclérose en plaques","Immunomodulateurs neurologiques","Interféron bêta","Natalizumab","Ocrélizumab"],"d":["La **sclérose en plaques** (SEP) est une maladie inflammatoire du système nerveux central, souvent chez l'adulte jeune, évoluant par **poussées** (troubles visuels, sensitifs, moteurs, de l'équilibre) puis parfois de façon progressive. Les **traitements de fond** diminuent les poussées et ralentissent le handicap ; les **corticoïdes** à forte dose traitent les poussées."],"ma":["Les traitements de fond modulent ou suppriment la réaction immunitaire dirigée contre la myéline : **immunomodulateurs** (interférons, glatiramère, tériflunomide, diméthylfumarate) ou **immunosuppresseurs** plus puissants (fingolimod, natalizumab, anti-CD20)."],"sch":null,"m":[{"dci":"Interféron bêta","br":"Avonex®, Rebif®, Plegridy®","pr":"injections SC ou IM"},{"dci":"Acétate de glatiramère","br":"Copaxone®","pr":"injection SC"},{"dci":"Tériflunomide, diméthylfumarate","br":"Aubagio®, Tecfidera®","pr":"voie orale"},{"dci":"Fingolimod","br":"Gilenya®","pr":"oral (surveillance cardiaque à la 1re prise)"},{"dci":"Natalizumab","br":"Tysabri®","pr":"perfusion mensuelle (risque de LEMP)"},{"dci":"Ocrélizumab, ofatumumab","br":"Ocrevus® (IV tous les 6 mois), Kesimpta® (SC)","pr":"anti-CD20"},{"dci":"Méthylprednisolone","br":"Solumédrol®","pr":"poussée : 1 g/jour IV pendant 3 à 5 jours"}],"ind":["**SEP rémittente** (traitement de fond), formes actives ou très actives (immunosuppresseurs)","Formes progressives (ocrélizumab dans certains cas)","**Poussée** invalidante (bolus de corticoïdes)"],"ci":["Infections actives, immunodépression ; tuberculose non traitée","Grossesse (tériflunomide, fingolimod : tératogènes ; avis spécialisé pour les autres)","Fingolimod : troubles du rythme, bradycardie, maladie cardiaque"],"ef":["Interférons : **syndrome pseudo-grippal** après l'injection, réactions au point d'injection, dépression","Glatiramère : réaction au point d'injection, flush","Diméthylfumarate : bouffées de chaleur, troubles digestifs","Anti-CD20 : réactions à la perfusion"],"eg":["**Infections** graves et opportunistes ; **LEMP** (leucoencéphalopathie multifocale progressive) sous natalizumab (virus JC)","Fingolimod : **bradycardie** à la première dose, œdème maculaire","Hépatite, cytopénies (interférons, tériflunomide)"],"it":[],"v":[],"sc":["Symptômes de poussée (vision, force, sensibilité, équilibre), fatigue, humeur","Signes d'infection ; troubles neurologiques nouveaux (LEMP)","Pendant les perfusions : constantes, signes allergiques ; glycémie et tension sous bolus de corticoïdes"],"sb":["**NFS, bilan hépatique** réguliers, sérologie JC (natalizumab), lymphocytes ; IRM de suivi"],"p":[],"edu":[],"cat":[],"r":["Traitements de fond : immunomodulateurs ou immunosuppresseurs ; **poussée = bolus de méthylprednisolone**","Interféron : syndrome pseudo-grippal (paracétamol, injection le soir)","Natalizumab : **LEMP** ; fingolimod : surveillance cardiaque 6 h à la 1re dose","Infections ; pas de vaccin vivant ; grossesse à planifier"],"err":[],"q":[],"f":["m:corticoides","m:biotherapies"],"_l":1},
{"n":"Myorelaxants et antispastiques","i":"antispastiques","s":"neuro","nn":["Myorelaxants centraux","Antispastiques","Myorelaxants","Baclofène","Thiocolchicoside","Dantrolène","Toxine botulique"],"d":["Les **antispastiques** diminuent la **spasticité** (raideur musculaire excessive) des maladies neurologiques : sclérose en plaques, lésions de la moelle, AVC, paralysie cérébrale. Les **myorelaxants** sont utilisés plus ponctuellement pour les contractures douloureuses (lombalgie)."],"ma":["Le **baclofène** stimule les récepteurs GABA-B de la moelle et freine les réflexes excessifs. Le **dantrolène** bloque la libération du calcium dans le muscle (aussi antidote de l'hyperthermie maligne). La **toxine botulique**, injectée dans un muscle, bloque localement la libération d'acétylcholine."],"sch":null,"m":[{"dci":"Baclofène","br":"Liorésal®, Lioresal intrathécal","pr":"oral ou pompe intrathécale"},{"dci":"Dantrolène","br":"Dantrium®","pr":"spasticité ; IV dans l'hyperthermie maligne"},{"dci":"Tizanidine","br":"Sirdalud® (ATU)","pr":"spasticité"},{"dci":"Toxine botulique","br":"Botox®, Dysport®","pr":"injections intramusculaires ciblées"},{"dci":"Thiocolchicoside, méthocarbamol","br":"Miorel®, Lumirelax®","pr":"contractures (usage restreint)"}],"ind":["**Spasticité** : SEP, lésion médullaire, AVC, paralysie cérébrale","Contractures musculaires douloureuses aiguës (courte durée)","Hyperthermie maligne (dantrolène IV), dystonies (toxine botulique)"],"ci":["Baclofène : épilepsie non contrôlée (prudence), troubles psychiatriques, insuffisance rénale (adapter)","Thiocolchicoside : **grossesse**, allaitement, femme sans contraception (génotoxicité)","Dantrolène : insuffisance hépatique"],"ef":["**Somnolence**, vertiges, **faiblesse musculaire**, fatigue","Nausées, confusion (baclofène chez la personne âgée)","Toxine : faiblesse transitoire du muscle injecté"],"eg":["**Chutes** (faiblesse, somnolence)","**Syndrome de sevrage du baclofène** à l'arrêt brutal ou en cas de panne de pompe : hallucinations, convulsions, hyperthermie, rigidité (urgence)","Dantrolène : hépatite ; thiocolchicoside : convulsions"],"it":[],"v":[],"sc":["**Tonus**, raideur, spasmes, autonomie, installation","Vigilance, équilibre, chutes","Signes de sevrage si oubli ou panne de pompe"],"sb":["Bilan hépatique (dantrolène), créatinine (baclofène)"],"p":[],"edu":[],"cat":[],"r":["Spasticité : baclofène, dantrolène, toxine botulique","**Baclofène : arrêt progressif** (sevrage grave)","Somnolence et chutes ; thiocolchicoside : 7 jours maximum, contre-indiqué pendant la grossesse"],"err":[],"q":[],"f":["m:sep"],"_l":1},
{"n":"Antidépresseurs ISRS et IRSNa","i":"isrs","s":"psy","nn":["Antidépresseurs inhibiteurs sélectifs de la recapture de la sérotonine (ISRS)","Antidépresseurs inhibiteurs de la recapture de la sérotonine et de la noradrénaline (IRSNa)","ISRS","IRSNa","Sertraline","Escitalopram","Venlafaxine"],"d":["Les **ISRS** et les **IRSNa** sont les **antidépresseurs de première intention** : épisode dépressif caractérisé, troubles anxieux (anxiété généralisée, trouble panique, phobie sociale), trouble obsessionnel compulsif, stress post-traumatique.","Leur effet n'apparaît qu'après **2 à 4 semaines** ; le début du traitement est une période à risque (**levée d'inhibition**) qui impose une surveillance du risque suicidaire."],"ma":["Ils bloquent la **recapture** de la sérotonine (ISRS), ou de la sérotonine et de la noradrénaline (IRSNa), dans la synapse : ces neurotransmetteurs restent plus longtemps actifs. L'amélioration de l'humeur résulte d'adaptations progressives des neurones, d'où le délai d'action."],"sch":{"k":"synapse","cap":"Les antidépresseurs bloquent la recapture : plus de sérotonine dans la synapse."},"m":[{"dci":"Sertraline","br":"Zoloft®","pr":"ISRS, bien toléré (cardiaque)"},{"dci":"Escitalopram, citalopram","br":"Seroplex®, Seropram®","pr":"ISRS (QT long à forte dose)"},{"dci":"Fluoxétine","br":"Prozac®","pr":"ISRS à demi-vie longue"},{"dci":"Paroxétine","br":"Deroxat®","pr":"ISRS (syndrome de sevrage marqué)"},{"dci":"Venlafaxine","br":"Effexor®","pr":"IRSNa (hypertension à forte dose)"},{"dci":"Duloxétine","br":"Cymbalta®","pr":"IRSNa, aussi douleurs neuropathiques"}],"ind":["**Épisode dépressif caractérisé** modéré à sévère","**Troubles anxieux** : anxiété généralisée, trouble panique, phobie sociale, TOC, stress post-traumatique","Douleurs neuropathiques, fibromyalgie (duloxétine)"],"ci":["Association aux **IMAO** (syndrome sérotoninergique) ; délai à respecter lors du changement","Citalopram, escitalopram : **allongement du QT**","Prudence : épilepsie, trouble bipolaire (virage maniaque), troubles de la coagulation"],"ef":["**Nausées**, troubles digestifs (premières semaines)","Céphalées, insomnie ou somnolence, nervosité au début","**Troubles sexuels** (baisse de la libido, troubles de l'érection ou de l'orgasme)","Sueurs, prise de poids possible"],"eg":["**Levée d'inhibition** : passage à l'acte suicidaire au début du traitement (énergie qui revient avant l'humeur), surtout avant 25 ans","**Syndrome sérotoninergique** : agitation, confusion, sueurs, fièvre, tremblements, myoclonies, diarrhée (urgence)","**Hyponatrémie** (personne âgée), **saignements** (avec AINS, antiagrégants, anticoagulants)","Virage maniaque, QT long, **syndrome de sevrage** à l'arrêt brutal"],"it":["**Tramadol, triptans, linézolide, IMAO, millepertuis, lithium** : syndrome sérotoninergique","**AINS, aspirine, anticoagulants** : risque hémorragique","Médicaments allongeant le QT (citalopram, escitalopram)"],"v":["Voie orale, une prise par jour (le matin si insomnie), dose de départ faible puis augmentation","**Durée** : au moins **6 mois à 1 an après la rémission** pour un premier épisode","**Arrêt progressif** sur plusieurs semaines (vertiges, sensations de « décharges électriques », irritabilité, insomnie si arrêt brutal)"],"sc":["**Humeur**, **idées suicidaires** (en parler directement), sommeil, appétit, comportement, en particulier les premières semaines","Tolérance digestive, agitation, virage de l'humeur (euphorie, excitation)","Signes de syndrome sérotoninergique ; observance"],"sb":["**Natrémie** chez la personne âgée ; ECG si citalopram ou escitalopram à risque"],"p":["Personne âgée : hyponatrémie, chutes, saignements ; sertraline ou escitalopram à faible dose","Enfant et adolescent : fluoxétine en seconde intention ; surveillance rapprochée du risque suicidaire","Grossesse et allaitement : sertraline souvent préférée ; ne pas arrêter brutalement ; surveiller le nouveau-né","Insuffisance hépatique : doses réduites"],"edu":["L'effet demande **2 à 4 semaines** ; les effets indésirables diminuent souvent avant","Ne pas arrêter seul, même en se sentant mieux ; arrêt progressif avec le médecin","**Signaler immédiatement** des idées noires, une agitation inhabituelle","Éviter l'alcool ; pas d'automédication (millepertuis, tramadol, AINS)"],"cat":["Idées suicidaires exprimées : rester avec le patient, sécuriser l'environnement, prévenir le médecin, tracer","Agitation, sueurs, fièvre, tremblements, diarrhée : prévenir en urgence (syndrome sérotoninergique)","Euphorie, excitation, insomnie sans fatigue : prévenir (virage maniaque)"],"r":["Première intention de la dépression et des troubles anxieux ; **délai d'action 2 à 4 semaines**","**Levée d'inhibition** : surveiller le risque suicidaire au début","**Syndrome sérotoninergique** (tramadol, triptans, IMAO, linézolide) ; hyponatrémie ; saignements","Durée 6 mois à 1 an après rémission ; **arrêt progressif**"],"err":[],"q":[{"q":"Pourquoi le risque suicidaire est-il plus élevé au début d'un traitement antidépresseur ?","o":["Parce que le médicament est toxique","Parce que l'énergie peut revenir avant l'amélioration de l'humeur (levée d'inhibition)","Parce que le patient prend trop de comprimés"],"a":1,"e":"Le patient retrouve l'élan pour agir alors que les idées noires persistent : surveillance rapprochée."},{"q":"Quels signes évoquent un syndrome sérotoninergique ?","o":["Une bradycardie et une hypothermie","Une agitation, des sueurs, de la fièvre, des tremblements et des myoclonies","Une constipation isolée"],"a":1,"e":"Le syndrome sérotoninergique associe signes neuropsychiques, neuromusculaires et végétatifs : c'est une urgence."}],"f":["psychotropes","m:autres-ad","m:benzodiazepines"]},
{"n":"Autres antidépresseurs : tricycliques, IMAO, mirtazapine","i":"autres-ad","s":"psy","nn":["Antidépresseurs tricycliques","Inhibiteurs de la monoamine oxydase (IMAO)","Autres antidépresseurs","Amitriptyline","Clomipramine","Mirtazapine"],"d":["En dehors des ISRS et IRSNa, d'autres antidépresseurs sont utilisés en **seconde intention** ou dans des situations particulières : **tricycliques** (efficaces mais moins bien tolérés et dangereux en surdosage), **IMAO** (dépressions résistantes), **mirtazapine** (sédative, utile en cas d'insomnie et de perte d'appétit), agomélatine, vortioxétine, eskétamine."],"ma":["Les **tricycliques** bloquent la recapture de la sérotonine et de la noradrénaline mais aussi des récepteurs de l'acétylcholine, de l'histamine et alpha (d'où leurs nombreux effets indésirables). Les **IMAO** bloquent l'enzyme qui dégrade les monoamines. La **mirtazapine** augmente la libération de sérotonine et de noradrénaline et bloque l'histamine (sédation)."],"sch":{"k":"synapse","cap":"Les IMAO bloquent la dégradation des neurotransmetteurs ; les tricycliques bloquent leur recapture."},"m":[{"dci":"Amitriptyline","br":"Laroxyl®","pr":"tricyclique ; aussi douleurs neuropathiques (faibles doses)"},{"dci":"Clomipramine","br":"Anafranil®","pr":"tricyclique ; dépression, TOC"},{"dci":"Mirtazapine","br":"Norset®","pr":"sédative, le soir"},{"dci":"Agomélatine","br":"Valdoxan®","pr":"surveillance hépatique"},{"dci":"Moclobémide, iproniazide","br":"Moclamine®, Marsilid®","pr":"IMAO"},{"dci":"Eskétamine","br":"Spravato®","pr":"spray nasal, dépression résistante, en milieu médical"}],"ind":["**Dépression résistante** ou sévère, dépression avec insomnie et perte d'appétit (mirtazapine)","TOC (clomipramine), douleurs neuropathiques et céphalées chroniques (amitriptyline), énurésie"],"ci":["Tricycliques : **glaucome à angle fermé**, **adénome de prostate**, **infarctus récent**, troubles de la conduction","IMAO : association aux ISRS, IRSNa, tricycliques, tramadol, triptans (syndrome sérotoninergique) ; phéochromocytome","Agomélatine : insuffisance hépatique, personne âgée de plus de 75 ans"],"ef":["Tricycliques : **effets anticholinergiques** (bouche sèche, constipation, rétention urinaire, troubles de la vision, confusion), **hypotension orthostatique**, somnolence, prise de poids","Mirtazapine : **somnolence**, **prise de poids** et augmentation de l'appétit","IMAO : hypotension orthostatique, insomnie"],"eg":["Tricycliques : **toxicité cardiaque grave en cas de surdosage** (élargissement du QRS, troubles du rythme, convulsions, coma) : risque majeur chez un patient suicidaire","IMAO : **crise hypertensive** avec les aliments riches en tyramine (fromages affinés, charcuterie, vin rouge, bière) pour les IMAO non sélectifs ; syndrome sérotoninergique","Agomélatine : hépatite ; mirtazapine : agranulocytose (rare)"],"it":[],"v":[],"sc":["Humeur, idées suicidaires","Tension couchée-debout, chutes, transit, mictions, confusion (tricycliques)","Poids, vigilance (mirtazapine)"],"sb":["ECG avant un tricyclique (sujet âgé, cardiaque) ; bilan hépatique (agomélatine) ; NFS si fièvre (mirtazapine)"],"p":[],"edu":[],"cat":[],"r":["Seconde intention ; tricycliques **anticholinergiques**, **mortels en surdosage** (cœur)","IMAO : **tyramine** (fromages, charcuterie, vin) et interactions sérotoninergiques","Mirtazapine : sédative, prise de poids, le soir"],"err":[],"q":[],"f":["psychotropes","m:isrs"],"_l":1},
{"n":"Benzodiazépines et hypnotiques","i":"benzodiazepines","s":"psy","nn":["Anxiolytiques benzodiazépines","Anxiolytiques non benzodiazépiniques","Hypnotiques benzodiazépines","Hypnotiques apparentés aux benzodiazépines","Traitements des troubles du sommeil","Zolpidem","Hydroxyzine"],"d":["Les **benzodiazépines** sont **anxiolytiques**, **hypnotiques**, anticonvulsivantes et myorelaxantes. Les **hypnotiques apparentés** (zolpidem, zopiclone) traitent l'insomnie. Efficaces à court terme, ils exposent à la **dépendance**, à la **tolérance** et, chez la personne âgée, aux **chutes** et aux troubles de la mémoire : leur durée de prescription est **limitée**."],"ma":["Ils renforcent l'action du **GABA**, principal neurotransmetteur inhibiteur du cerveau, en se fixant sur son récepteur : apaisement, sommeil, relâchement musculaire, effet anticonvulsivant."],"sch":{"k":"synapse","cap":"Les benzodiazépines renforcent le frein exercé par le GABA."},"m":[{"dci":"Alprazolam, bromazépam","br":"Xanax®, Lexomil®","pr":"anxiolytiques, demi-vie courte à moyenne"},{"dci":"Oxazépam, lorazépam","br":"Séresta®, Témesta®","pr":"demi-vie courte (préférés chez la personne âgée)"},{"dci":"Diazépam, clorazépate","br":"Valium®, Tranxène®","pr":"demi-vie longue (sevrage alcoolique)"},{"dci":"Zolpidem, zopiclone","br":"Stilnox®, Imovane®","pr":"hypnotiques apparentés"},{"dci":"Hydroxyzine","br":"Atarax®","pr":"anxiolytique non benzodiazépinique (antihistaminique)"},{"dci":"Mélatonine","br":"Circadin®","pr":"insomnie après 55 ans"},{"dci":"Flumazénil","br":"Anexate®","pr":"antidote (voir antidotes)"}],"ind":["**Anxiété** aiguë, trouble anxieux en attendant l'effet d'un antidépresseur","**Insomnie** occasionnelle ou transitoire","**Sevrage alcoolique**, crise convulsive, sédation, prémédication"],"ci":["**Insuffisance respiratoire sévère**, **syndrome d'apnées du sommeil**","**Myasthénie**, insuffisance hépatique sévère","Prudence : personne âgée, antécédent d'addiction, grossesse"],"ef":["**Somnolence** diurne, baisse de la vigilance","**Troubles de la mémoire** (amnésie antérograde), difficultés de concentration","Faiblesse musculaire, troubles de l'équilibre"],"eg":["**Chutes** et fractures (personne âgée), confusion","**Dépendance**, tolérance, **syndrome de sevrage** à l'arrêt brutal (anxiété, insomnie, tremblements, voire **convulsions**)","**Dépression respiratoire** en association avec les opioïdes ou l'alcool","Réactions paradoxales (agitation, agressivité), comportements automatiques (zolpidem)"],"it":[],"v":[],"sc":["**Vigilance**, somnolence, confusion, **chutes**, équilibre","Fréquence respiratoire (surtout avec opioïdes), qualité du sommeil, anxiété","Signes de dépendance ou de sevrage"],"sb":["Aucune surveillance biologique spécifique"],"p":[],"edu":[],"cat":[],"r":["Anxiolytiques et hypnotiques : renforcent le **GABA**","**Durée limitée** : 4 semaines (insomnie), 12 semaines (anxiété) ; **arrêt progressif**","**Chutes**, mémoire, dépendance ; dépression respiratoire avec opioïdes et alcool","Antidote : **flumazénil** (prudence)"],"err":[],"q":[],"f":["psychotropes","m:isrs","m:alcool","m:antidotes"],"_l":1},
{"n":"Antipsychotiques","i":"antipsychotiques","s":"psy","nn":["Antipsychotiques de première génération","Antipsychotiques de deuxième génération","Neuroleptiques","Halopéridol","Rispéridone","Olanzapine","Clozapine"],"d":["Les **antipsychotiques** (neuroleptiques) traitent les **troubles psychotiques** (schizophrénie, délires), les **épisodes maniaques** et l'**agitation**. On distingue la **1re génération** (halopéridol, chlorpromazine), avec plus d'effets neurologiques, et la **2e génération** (rispéridone, olanzapine, aripiprazole, quétiapine, clozapine), avec plus d'effets métaboliques."],"ma":["Ils bloquent les **récepteurs D2 de la dopamine** dans les voies cérébrales impliquées dans le délire et les hallucinations. Ce blocage dans d'autres voies explique les effets indésirables : syndrome extrapyramidal (voie motrice), hyperprolactinémie. Les antipsychotiques de 2e génération bloquent aussi des récepteurs de la sérotonine."],"sch":{"k":"synapse","cap":"Les antipsychotiques bloquent les récepteurs D2 de la dopamine."},"m":[{"dci":"Halopéridol","br":"Haldol®","pr":"1re génération ; gouttes, injectable"},{"dci":"Loxapine, cyamémazine","br":"Loxapac®, Tercian®","pr":"1re génération, sédatifs (agitation)"},{"dci":"Rispéridone","br":"Risperdal®","pr":"2e génération"},{"dci":"Olanzapine","br":"Zyprexa®","pr":"2e génération (prise de poids importante)"},{"dci":"Aripiprazole","br":"Abilify®","pr":"2e génération (peu d'effets métaboliques)"},{"dci":"Quétiapine, amisulpride","br":"Xeroquel®, Solian®","pr":"2e génération"},{"dci":"Clozapine","br":"Leponex®","pr":"schizophrénie résistante ; surveillance de la NFS"}],"ind":["**Schizophrénie** et autres troubles psychotiques","**Épisode maniaque**, trouble bipolaire (traitement de fond pour certains)","**Agitation** aiguë, délirium sévère (faibles doses, durée courte)","Nausées et vomissements en soins palliatifs (halopéridol)"],"ci":["**Maladie de Parkinson** (1re génération ; clozapine ou quétiapine possibles à faible dose)","**Allongement du QT**, troubles du rythme","Antécédent de **syndrome malin des neuroleptiques**, d'agranulocytose (clozapine)"],"ef":["**Sédation**, somnolence","**Prise de poids**, augmentation de l'appétit (2e génération, surtout olanzapine et clozapine)","**Effets extrapyramidaux** : dyskinésie aiguë, **akathisie** (impossibilité de rester en place), syndrome parkinsonien (1re génération surtout)","**Hyperprolactinémie** : troubles des règles, galactorrhée, troubles sexuels"],"eg":["**Syndrome malin des neuroleptiques** : **fièvre élevée, rigidité, troubles de conscience**, instabilité tensionnelle, CPK élevées (urgence vitale)","**Syndrome métabolique** : diabète, dyslipidémie, obésité","**Troubles du rythme** (QT long), mort subite","**Dyskinésies tardives** (mouvements involontaires de la bouche, parfois irréversibles)"],"it":[],"v":[],"sc":["**Température**, **rigidité**, conscience (syndrome malin)","**Mouvements anormaux**, akathisie, tremblements","**Poids, IMC, tour de taille**, tension, transit (clozapine), sédation"],"sb":["**Bilan métabolique** (glycémie, bilan lipidique) avant, à 1 et 3 mois puis chaque année ; **ECG** avant et en cas de facteur de risque ; prolactine si symptômes ; **NFS hebdomadaire pendant 18 semaines puis mensuelle sous clozapine** ; CPK si suspicion de syndrome malin"],"p":[],"edu":[],"cat":[],"r":["Bloquent la **dopamine D2** : psychoses, manie, agitation","1re génération : **extrapyramidal** ; 2e génération : **métabolique** (poids, glycémie, lipides)","**Syndrome malin** : fièvre + rigidité + troubles de conscience = urgence","QT long (ECG) ; clozapine : **NFS** (agranulocytose), constipation"],"err":[],"q":[],"f":["neuroleptiques","m:nap","m:lithium"],"_l":1},
{"n":"Antipsychotiques injectables à action prolongée","i":"nap","s":"psy","nn":["Antipsychotiques injectables à action prolongée","NAP","Neuroleptiques à action prolongée","Palipéridone","Halopéridol décanoate"],"d":["Les **antipsychotiques injectables à action prolongée** (APAP, anciennement NAP) libèrent le médicament pendant **2 semaines à 6 mois** après une seule injection IM. Ils améliorent l'**observance** et diminuent les **rechutes** et les hospitalisations dans la schizophrénie."],"ma":["Le principe actif est lié à une molécule qui le libère lentement depuis le muscle (ester, microsphères, nanocristaux) : la concentration reste stable entre deux injections."],"sch":{"k":"angles","cap":"Injection intramusculaire profonde, dans le deltoïde ou le muscle fessier selon le produit."},"m":[{"dci":"Palipéridone","br":"Xeplion® (mensuel), Trevicta® (trimestriel), Byannli® (semestriel)","pr":"deltoïde ou fessier"},{"dci":"Rispéridone","br":"Risperdal Consta® (toutes les 2 semaines)","pr":"microsphères, reconstitution"},{"dci":"Aripiprazole","br":"Abilify Maintena® (mensuel)","pr":"deltoïde ou fessier"},{"dci":"Halopéridol décanoate","br":"Haldol Décanoas®","pr":"toutes les 4 semaines, solution huileuse"},{"dci":"Zuclopenthixol décanoate","br":"Clopixol AP®","pr":"toutes les 2 à 4 semaines"},{"dci":"Olanzapine pamoate","br":"Zypadhera®","pr":"**surveillance de 3 heures** après l'injection"}],"ind":["**Schizophrénie** stabilisée, notamment en cas de difficulté d'observance ou de rechutes répétées","Trouble bipolaire (aripiprazole, rispéridone dans certains cas)"],"ci":["Mêmes contre-indications que la forme orale ; pas d'utilisation dans l'agitation aiguë (délai d'action)","Tolérance de la forme orale à vérifier avant la première injection"],"ef":["Douleur, induration ou nodule au point d'injection","Mêmes effets que les antipsychotiques oraux : prise de poids, sédation, effets extrapyramidaux, hyperprolactinémie"],"eg":["**Syndrome post-injection de l'olanzapine** : sédation importante, confusion, voire coma dans les 3 heures (passage rapide dans le sang)","Syndrome malin, effets indésirables **prolongés** (le médicament ne peut pas être retiré)"],"it":[],"v":[],"sc":["À chaque injection : **état clinique** (humeur, symptômes psychotiques), tolérance, effets extrapyramidaux, poids","Point d'injection précédent","Après l'olanzapine pamoate : vigilance, conscience"],"sb":["Bilan métabolique et ECG selon les recommandations des antipsychotiques"],"p":[],"edu":[],"cat":[],"r":["**IM profonde** (deltoïde ou fessier), sans masser, en alternant les côtés","Améliorent l'**observance**, diminuent les rechutes","Olanzapine pamoate : **surveillance de 3 heures** après injection","Effets indésirables prolongés ; dates planifiées"],"err":[],"q":[],"f":["neuroleptiques","m:antipsychotiques"],"_l":1},
{"n":"Lithium et thymorégulateurs","i":"lithium","s":"psy","nn":["Thymorégulateurs","Lithium","Téralithe","Antiépileptiques utilisés comme thymorégulateurs","Régulateurs de l'humeur"],"d":["Les **thymorégulateurs** préviennent les rechutes maniaques et dépressives du **trouble bipolaire** et traitent les épisodes aigus. Le **lithium** est le traitement de référence, avec un effet préventif du suicide démontré ; certains antiépileptiques (valproate, lamotrigine, carbamazépine) et antipsychotiques de 2e génération sont aussi utilisés."],"ma":["Le mécanisme du lithium est complexe : il stabilise la transmission nerveuse en agissant sur des messagers intracellulaires. Il est éliminé par le **rein** comme le sodium : tout ce qui retient le sodium (déshydratation, régime sans sel, certains médicaments) fait monter la lithémie."],"sch":{"k":"fenetre","cap":"Lithium : marge thérapeutique étroite, surveillance par la lithémie."},"m":[{"dci":"Lithium","br":"Téralithe® 250 et Téralithe® LP 400","pr":"référence"},{"dci":"Valproate (divalproate, valpromide)","br":"Dépakote®, Dépamide®","pr":"manie ; tératogène"},{"dci":"Lamotrigine","br":"Lamictal®","pr":"prévention des dépressions bipolaires"},{"dci":"Carbamazépine","br":"Tégrétol®","pr":"alternative"},{"dci":"Quétiapine, aripiprazole, olanzapine","br":"Xeroquel®, Abilify®, Zyprexa®","pr":"antipsychotiques thymorégulateurs"}],"ind":["**Trouble bipolaire** : prévention des rechutes, épisode maniaque","Dépression résistante (lithium en association)"],"ci":["Lithium : **insuffisance rénale**, **régime sans sel strict**, déshydratation, insuffisance cardiaque instable, **1er trimestre de grossesse** (malformations cardiaques), allaitement","Valproate : femme en âge de procréer sans programme de prévention des grossesses"],"ef":["Lithium : **tremblement fin des mains**, **soif et urines abondantes** (polyuro-polydipsie), prise de poids, troubles digestifs au début, acné","Lithium : **hypothyroïdie** et goitre, hyperparathyroïdie"],"eg":["**Intoxication au lithium** : troubles digestifs (diarrhée, vomissements), **tremblements grossiers**, troubles de l'équilibre et de la parole, **confusion**, somnolence, convulsions, coma, troubles du rythme","**Insuffisance rénale chronique**, diabète insipide néphrogénique (traitement prolongé)","Valproate : hépatite, pancréatite, tératogénicité ; lamotrigine : réactions cutanées graves"],"it":[],"v":[],"sc":["**Tremblements** (fins ou grossiers), troubles digestifs, équilibre, conscience, parole","**Hydratation**, soif, diurèse, poids","Humeur (virage maniaque ou dépressif), observance"],"sb":["**Lithémie** (zone thérapeutique le plus souvent 0,5 à 0,8 mmol/L, jusqu'à 1,2 avec la forme LP selon la prescription ; toxique au-delà), **créatinine** et **TSH** tous les 6 à 12 mois, calcémie"],"p":[],"edu":[],"cat":[],"r":["Lithium : référence du trouble bipolaire, **marge étroite**","**Lithémie à 12 h** de la prise ; créatinine et TSH régulières","Intoxication : digestif + tremblements grossiers + confusion + ataxie","**AINS, IEC, ARA II, diurétiques, déshydratation, régime sans sel** = lithémie augmentée"],"err":[],"q":[],"f":["psychotropes","m:antiepileptiques","m:antipsychotiques"],"_l":1},
{"n":"Psychostimulants (TDAH)","i":"tdah","s":"psy","nn":["Psychostimulants","Traitements du TDAH","Méthylphénidate","Ritaline"],"d":["Le **méthylphénidate** traite le **trouble du déficit de l'attention avec ou sans hyperactivité (TDAH)** chez l'enfant à partir de 6 ans, l'adolescent et l'adulte, quand les mesures psychoéducatives sont insuffisantes. Il est aussi utilisé dans la **narcolepsie**."],"ma":["Il bloque la recapture de la **dopamine** et de la **noradrénaline** dans les régions du cerveau impliquées dans l'attention et le contrôle de l'impulsivité."],"sch":null,"m":[{"dci":"Méthylphénidate","br":"Ritaline®, Ritaline LP®, Concerta LP®, Quasym LP®, Medikinet®","pr":"libération immédiate ou prolongée"},{"dci":"Lisdexamfétamine, atomoxétine","br":"Xelstrana®, Strattera®","pr":"alternatives selon disponibilité"}],"ind":["**TDAH** de l'enfant (à partir de 6 ans), de l'adolescent et de l'adulte, dans le cadre d'une prise en charge globale","**Narcolepsie**"],"ci":["**Troubles cardiovasculaires** (HTA sévère, troubles du rythme, cardiopathie), hyperthyroïdie","Troubles psychiatriques sévères (psychose, trouble bipolaire non stabilisé, idées suicidaires), anorexie mentale","Glaucome, association aux IMAO"],"ef":["**Perte d'appétit**, perte de poids","**Insomnie**, céphalées, douleurs abdominales","Nervosité, irritabilité, tics"],"eg":["**Ralentissement de la croissance** (taille, poids)","Hypertension, tachycardie, troubles du rythme","Troubles psychiatriques (anxiété, agressivité, symptômes psychotiques), mésusage et dépendance"],"it":[],"v":[],"sc":["**Poids, taille** (courbe de croissance), appétit","**Tension artérielle, pouls**","Sommeil, humeur, comportement, tics, efficacité (scolarité)"],"sb":["Aucune surveillance biologique spécifique ; bilan cardiaque avant traitement selon les antécédents"],"p":[],"edu":[],"cat":[],"r":["TDAH à partir de 6 ans, avec prise en charge globale","**Le matin**, pas le soir (insomnie) ; **croissance, appétit, tension, pouls**","Stupéfiant : prescription initiale hospitalière, ordonnance sécurisée 28 jours"],"err":[],"q":[],"f":["psychotropes","m:isrs"],"_l":1},
{"n":"Traitements de substitution aux opioïdes","i":"tso","s":"psy","nn":["Traitements de substitution aux opioïdes","TSO","Méthadone","Buprénorphine","Subutex","Antagonistes des opioïdes dans les addictions"],"d":["Les **traitements de substitution aux opioïdes** (méthadone, buprénorphine) remplacent l'héroïne ou les opioïdes détournés par un médicament à action prolongée, pris quotidiennement. Ils réduisent le manque, les overdoses, les infections (VIH, hépatites) et permettent une réinsertion."],"ma":["La **méthadone** est un agoniste complet des récepteurs opioïdes à longue durée d'action. La **buprénorphine** est un agoniste partiel, avec un **effet plafond** sur la dépression respiratoire (plus sûre) ; associée à la **naloxone** (Suboxone®), elle décourage l'injection. Elles occupent les récepteurs et suppriment le manque sans effet « flash »."],"sch":null,"m":[{"dci":"Méthadone","br":"sirop, gélules","pr":"stupéfiant ; initiation en CSAPA ou à l'hôpital"},{"dci":"Buprénorphine haut dosage","br":"Subutex®, Orobupré® (lyophilisat), génériques","pr":"sublingual"},{"dci":"Buprénorphine + naloxone","br":"Suboxone®","pr":"sublingual (limite le mésusage par injection)"},{"dci":"Buprénorphine injectable LP","br":"Buvidal®","pr":"SC hebdomadaire ou mensuelle"},{"dci":"Naloxone (kits)","br":"Nyxoid®, Prenoxad®","pr":"remis aux patients et à l'entourage"}],"ind":["**Dépendance aux opioïdes** (héroïne, morphiniques détournés)","Maintien du traitement lors d'une hospitalisation ou d'une incarcération (ne pas interrompre)"],"ci":["Méthadone : insuffisance respiratoire sévère, **QT long**","Buprénorphine : insuffisance hépatique sévère, insuffisance respiratoire sévère","Association méthadone et buprénorphine, ou buprénorphine et agonistes opioïdes (sevrage)"],"ef":["**Constipation**, sueurs, somnolence, nausées","Troubles sexuels, prise de poids"],"eg":["**Overdose** (méthadone surtout) : coma, myosis, **dépression respiratoire** ; mortelle chez un enfant ou une personne non dépendante","**Allongement du QT**, torsades de pointes (méthadone)","Buprénorphine : **syndrome de sevrage précipité** si prise trop tôt après un opioïde ; hépatite ; complications de l'injection détournée"],"it":[],"v":[],"sc":["**Vigilance**, fréquence respiratoire, myosis (surdosage) ; signes de manque (bâillements, larmoiement, rhinorrhée, mydriase, frissons, douleurs, agitation)","Consommations associées (alcool, benzodiazépines), état général, humeur","Transit, dents"],"sb":["**ECG** (QT) avant la méthadone et lors des augmentations ; bilan hépatique ; sérologies VIH, VHC, VHB ; dépistage urinaire selon le protocole"],"p":[],"edu":[],"cat":[],"r":["Méthadone (agoniste complet, **QT**, overdose) ; buprénorphine (agoniste partiel, **sublinguale**, sevrage précipité si trop tôt)","Danger majeur : association à l'**alcool et aux benzodiazépines**","Stockage sécurisé (intoxication de l'enfant) ; **kit de naloxone**","Ne jamais interrompre un TSO lors d'une hospitalisation"],"err":[],"q":[],"f":["stupefiants","m:naloxone","m:opio-forts"],"_l":1},
{"n":"Alcool : sevrage et maintien de l'abstinence","i":"alcool","s":"psy","nn":["Traitements de l'alcoolodépendance","Traitements du sevrage alcoolique","Sevrage alcoolique","Acamprosate","Baclofène","Disulfirame","Vitamine B1"],"d":["Le **sevrage alcoolique** chez une personne dépendante peut être dangereux : **convulsions** et **delirium tremens** dans les 6 à 72 heures suivant l'arrêt. Il se prévient par les **benzodiazépines**, l'**hydratation** et la **vitamine B1**."],"ma":["Les **benzodiazépines** remplacent l'effet sédatif de l'alcool sur le GABA et préviennent les complications du sevrage. La **vitamine B1** (thiamine) prévient l'**encéphalopathie de Gayet-Wernicke**. L'**acamprosate** et la **naltrexone** diminuent l'envie de boire ; le **nalméfène** et le **baclofène** aident à réduire la consommation ; le **disulfirame** provoque un effet antabuse dissuasif."],"sch":null,"m":[{"dci":"Diazépam, oxazépam","br":"Valium®, Séresta®","pr":"sevrage (oxazépam si insuffisance hépatique)"},{"dci":"Thiamine (vitamine B1)","br":"Bévitine®","pr":"oral ou IV, avant tout apport de glucose"},{"dci":"Acamprosate","br":"Aotal®","pr":"maintien de l'abstinence"},{"dci":"Naltrexone","br":"Revia®","pr":"maintien de l'abstinence"},{"dci":"Nalméfène","br":"Selincro®","pr":"réduction de la consommation (à la demande)"},{"dci":"Baclofène","br":"Baclocur®","pr":"réduction de la consommation"},{"dci":"Disulfirame","br":"Espéral®","pr":"effet antabuse"}],"ind":["**Sevrage alcoolique** programmé ou non (hospitalisation, urgence)","**Maintien de l'abstinence** après sevrage, réduction de la consommation","Prévention et traitement de l'encéphalopathie de Gayet-Wernicke (vitamine B1)"],"ci":["Benzodiazépines : insuffisance respiratoire sévère, apnées du sommeil","Naltrexone et nalméfène : **traitement opioïde en cours** (sevrage brutal, perte de l'antalgie)","Disulfirame : cardiopathie, insuffisance hépatique, troubles psychiatriques sévères ; jamais à l'insu du patient"],"ef":["Benzodiazépines : somnolence","Acamprosate : diarrhée ; naltrexone et nalméfène : nausées, vertiges","Baclofène : somnolence, vertiges, troubles de l'humeur"],"eg":["**Delirium tremens** (sevrage non traité) : agitation, hallucinations, confusion, fièvre, sueurs, tachycardie","**Convulsions** de sevrage","**Encéphalopathie de Gayet-Wernicke** : confusion, troubles de la marche, troubles oculomoteurs (glucose sans vitamine B1)","Disulfirame + alcool : **effet antabuse** (flush, céphalées, vomissements, tachycardie, malaise) potentiellement grave"],"it":[],"v":[],"sc":["**Score de Cushman** régulièrement (toutes les heures puis espacé selon le protocole) : pouls, tension, tremblements, sueurs, agitation, hallucinations, fréquence respiratoire","**Conscience**, orientation, température, hydratation, sommeil","Vigilance (sédation excessive), chutes"],"sb":["Ionogramme (natrémie, kaliémie, **phosphorémie**, magnésémie), glycémie, bilan hépatique, NFS, TP"],"p":[],"edu":[],"cat":[],"r":["Sevrage : **benzodiazépines** selon le **score de Cushman**, hydratation, **vitamine B1**","**Vitamine B1 avant tout glucosé** (Gayet-Wernicke)","Delirium tremens et convulsions entre 6 et 72 h","Maintien : acamprosate, naltrexone (pas avec les opioïdes), baclofène, nalméfène, disulfirame"],"err":[],"q":[],"f":["m:benzodiazepines","m:tso"],"_l":1},
{"n":"Traitements de la dépendance au tabac","i":"nicotine","s":"psy","nn":["Traitements de la dépendance nicotinique","Substituts nicotiniques","Varénicline","Sevrage tabagique"],"d":["Le **tabac** est la première cause de mortalité évitable. Les **substituts nicotiniques** (patchs, gommes, pastilles, inhaleurs, sprays) doublent les chances d'arrêt ; la **varénicline** et le **bupropion** sont des alternatives sur prescription. L'association à un accompagnement (tabacologue, Tabac info service) augmente encore l'efficacité."],"ma":["Les **substituts nicotiniques** apportent la nicotine sans la combustion (ni goudrons ni monoxyde de carbone) : ils soulagent le manque. La **varénicline** stimule partiellement les récepteurs nicotiniques (moins de manque, moins de plaisir à fumer)."],"sch":null,"m":[{"dci":"Patchs de nicotine","br":"Nicopatch®, Nicotinell®, Niquitin®","pr":"16 h ou 24 h, plusieurs dosages"},{"dci":"Formes orales","br":"gommes, pastilles, comprimés sublinguaux, inhaleur, spray buccal","pr":"à la demande"},{"dci":"Varénicline","br":"génériques","pr":"sur prescription, 12 semaines"},{"dci":"Bupropion","br":"Zyban®","pr":"sur prescription (risque de convulsions)"}],"ind":["**Sevrage tabagique** ou réduction de la consommation","Fumeur hospitalisé (prévention du manque), grossesse (substituts privilégiés), avant une chirurgie"],"ci":["Substituts : aucune contre-indication absolue (y compris chez le cardiaque ou la femme enceinte, ils sont moins dangereux que le tabac) ; prudence après un infarctus très récent","Varénicline : prudence en cas d'antécédents psychiatriques ; insuffisance rénale sévère (adapter)","Bupropion : **épilepsie**, troubles alimentaires, trouble bipolaire"],"ef":["Patch : irritation cutanée, rêves vivaces (patch 24 h)","Formes orales : irritation de la bouche, hoquet, troubles digestifs","Varénicline : **nausées**, troubles du sommeil, rêves anormaux"],"eg":["**Signes de surdosage en nicotine** : nausées, palpitations, céphalées, sueurs, bouche pâteuse","Varénicline : troubles de l'humeur (à surveiller)","Bupropion : convulsions"],"it":[],"v":[],"sc":["Signes de **sous-dosage** (envie de fumer, irritabilité, nervosité, troubles du sommeil, faim) et de **surdosage** (nausées, palpitations, céphalées)","Consommation de cigarettes, humeur, poids"],"sb":["Monoxyde de carbone expiré (motivation, suivi) ; taux de clozapine ou d'olanzapine si arrêt du tabac"],"p":[],"edu":[],"cat":[],"r":["Substituts nicotiniques : patch + formes orales, dose adaptée à la dépendance, **3 mois au moins**","Sous-dosage = envie de fumer ; surdosage = nausées, palpitations, céphalées","Proposer des substituts à tout fumeur hospitalisé ; possibles pendant la grossesse","L'arrêt du tabac modifie les doses de clozapine et d'olanzapine"],"err":[],"q":[],"f":["m:antipsychotiques"],"_l":1}
]);
